.cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.tile {
  padding: 16px;
  border-radius: 10px;
  border: 1px solid #e4e4e7;
  background-color: #ffffff;
  color: #18181b;
}

.tile h3 {
  margin: 0 0 4px;
}

.tile p {
  margin: 0;
}

