.cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
  padding: 16px;
  font-family: system-ui, sans-serif;
}

.tile {
  padding: 16px;
  border-radius: 10px;
  border: 1px solid #e4e4e7;
  background-color: #ffffff;
  color: #18181b;
}

.tile h3 {
  margin: 0 0 4px;
}

.tile p {
  margin: 0;
}

/* ---- Solution ---- */
.tile {
  --bg: #ffffff;
  --fg: #18181b;
  --line: #e4e4e7;

  border: 1px solid var(--line);
  background-color: var(--bg);
  color: var(--fg);
}

.tile[data-theme="dark"] {
  --bg: #18181b;
  --fg: #fafafa;
  --line: #3f3f46;
}
